export const getDeleteTransactionUrl = (id: string) => {
  return `/api/transactions/${id}`;
};

/**
 * Removes the transaction and adjusts the account balance accordingly. Its split lines, tags and attached files are kept with it, so POST /api/trash/restore brings it back whole for the next 30 days.
 * @summary Delete a transaction
 */
export const deleteTransaction = async (
  id: string,
  options?: Parameters<typeof customFetch>[1],
): Promise<void> => {
  return customFetch<void>(getDeleteTransactionUrl(id), {
    ...options,
    method: "DELETE",
  });
};

export const getDeleteTransactionMutationKey = () => ["deleteTransaction"] as const;

export const getDeleteTransactionMutationOptions = <
  TError = ErrorType<ProblemDetails>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof deleteTransaction>>,
    TError,
    DeleteTransactionMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof deleteTransaction>>,
  TError,
  DeleteTransactionMutationVariables,
  TContext
> => {
  const mutationKey = getDeleteTransactionMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof deleteTransaction>>,
    DeleteTransactionMutationVariables
  > = (props) => {
    const { id } = props ?? {};

    return deleteTransaction(id, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type DeleteTransactionMutationResult = NonNullable<
  Awaited<ReturnType<typeof deleteTransaction>>
>;

export type DeleteTransactionMutationError = ErrorType<ProblemDetails>;
export type DeleteTransactionMutationVariables = { id: string };

/**
 * @summary Delete a transaction
 */
export const useDeleteTransaction = <TError = ErrorType<ProblemDetails>, TContext = unknown>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof deleteTransaction>>,
      TError,
      DeleteTransactionMutationVariables,
      TContext
    >;
    request?: SecondParameter<typeof customFetch>;
  },
  queryClient?: QueryClient,
): UseMutationResult<
  Awaited<ReturnType<typeof deleteTransaction>>,
  TError,
  DeleteTransactionMutationVariables,
  TContext
> => {
  return useMutation(getDeleteTransactionMutationOptions(options), queryClient);
};
