export const getUpdateTransactionUrl = (id: string) => {
  return `/api/transactions/${id}`;
};

/**
 * Replaces the transaction. Split lines are replaced wholesale rather than merged: send the full set you want to keep, or omit lines to turn a split back into a plain transaction. Tags are replaced the same way: send the full set, and an empty list or an absent tagIds clears them. Moving it to another account adjusts both balances.
 * @summary Update a transaction
 */
export const updateTransaction = async (
  id: string,
  updateTransactionRequest: UpdateTransactionRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<TransactionResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<TransactionResponse>(getUpdateTransactionUrl(id), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(updateTransactionRequest),
  });
};

export const getUpdateTransactionMutationKey = () => ["updateTransaction"] as const;

export const getUpdateTransactionMutationOptions = <
  TError = ErrorType<ProblemDetails>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof updateTransaction>>,
    TError,
    UpdateTransactionMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof updateTransaction>>,
  TError,
  UpdateTransactionMutationVariables,
  TContext
> => {
  const mutationKey = getUpdateTransactionMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof updateTransaction>>,
    UpdateTransactionMutationVariables
  > = (props) => {
    const { id, data } = props ?? {};

    return updateTransaction(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type UpdateTransactionMutationResult = NonNullable<
  Awaited<ReturnType<typeof updateTransaction>>
>;
export type UpdateTransactionMutationBody = UpdateTransactionRequest;
export type UpdateTransactionMutationError = ErrorType<ProblemDetails>;
export type UpdateTransactionMutationVariables = { id: string; data: UpdateTransactionRequest };

/**
 * @summary Update a transaction
 */
export const useUpdateTransaction = <TError = ErrorType<ProblemDetails>, TContext = unknown>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof updateTransaction>>,
      TError,
      UpdateTransactionMutationVariables,
      TContext
    >;
    request?: SecondParameter<typeof customFetch>;
  },
  queryClient?: QueryClient,
): UseMutationResult<
  Awaited<ReturnType<typeof updateTransaction>>,
  TError,
  UpdateTransactionMutationVariables,
  TContext
> => {
  return useMutation(getUpdateTransactionMutationOptions(options), queryClient);
};
